$ErrorActionPreference = 'Stop'
function Get-WmSha256([string]$WmPath) { $wmHashAlgorithm = [System.Security.Cryptography.SHA256]::Create(); $wmHashStream = [System.IO.File]::OpenRead($WmPath); try { return ([System.BitConverter]::ToString($wmHashAlgorithm.ComputeHash($wmHashStream))).Replace('-', '').ToLowerInvariant() } finally { $wmHashStream.Dispose(); $wmHashAlgorithm.Dispose() } }
$wmVolume = Get-Volume -DriveLetter D
if ($wmVolume.FileSystemLabel -ne 'THESIS_SSD' -or $wmVolume.UniqueId -ne '\\?\Volume{0a2f1ba9-0000-0000-0000-100000000000}\' -or $wmVolume.HealthStatus -ne 'Healthy' -or $wmVolume.SizeRemaining -lt 40000000000) { throw 'Required SSD identity/health/free-space gate failed' }
$wmCommit = 'd3e165ab49c3bb22c6eee3c2036748d306577936'
$wmRelative = 'docs/world-model-diagnostic-20261004/PROVENANCE-HANDOFF.md'
$wmSource = Join-Path (Get-Location).Path $wmRelative
$wmBlob = (git rev-parse ($wmCommit + ':' + $wmRelative)).Trim()
if ($LASTEXITCODE -ne 0) { throw 'Git blob identity unavailable' }
$wmWorkingBlob = (git hash-object --no-filters -- $wmRelative).Trim()
if ($LASTEXITCODE -ne 0 -or $wmWorkingBlob -ne $wmBlob) { throw 'Working bytes differ from immutable handoff blob' }
$wmSourceInfo = Get-Item -LiteralPath $wmSource
if ($wmSourceInfo.Length -gt 10000000) { throw 'New document exceeds handoff output cap' }
$wmSourceHash = Get-WmSha256 $wmSource
$wmTargetDirectory = 'D:\THESIS-BACKUPS\world-model-diagnostic-20261004\handoff-d3e165ab49c3bb22c6eee3c2036748d306577936'
if (Test-Path -LiteralPath $wmTargetDirectory) { throw 'Exclusive handoff destination already exists; preserve and reconcile rather than retry' }
[void](New-Item -ItemType Directory -Path $wmTargetDirectory)
$wmTarget = Join-Path $wmTargetDirectory 'PROVENANCE-HANDOFF.md'
[System.IO.File]::Copy($wmSource, $wmTarget, $false)
$wmTargetHash = Get-WmSha256 $wmTarget
$wmTargetInfo = Get-Item -LiteralPath $wmTarget
if ($wmSourceHash -ne $wmTargetHash -or $wmSourceInfo.Length -ne $wmTargetInfo.Length) { throw 'Handoff copy hash/size verification failed; partial retained' }
[ordered]@{ status='NEW_HANDOFF_WHOLE_FILE_AND_SINGLE_MEMBER_VERIFIED'; git_commit=$wmCommit; git_blob=$wmBlob; path=$wmRelative; bytes=$wmSourceInfo.Length; sha256=$wmSourceHash; ssd_path=$wmTarget; volume_label=$wmVolume.FileSystemLabel; volume_unique_id=$wmVolume.UniqueId; free_bytes_before=$wmVolume.SizeRemaining; health=$wmVolume.HealthStatus.ToString(); transfer='Native Windows copy; exclusive destination'; completed_packages_rearchived=0; historical_rebackups=0; external_requests_sent=0; scientific_execution=$false } | ConvertTo-Json -Depth 5
